// Webhook'tan gelen notu listeye ekler; istenirse hatırlatma zamanı kurar.
const okunan = $input.first().json;
const mevcut = (okunan.data && okunan.data.notlar) || okunan.notlar || [];
const notlar = Array.isArray(mevcut) ? [...mevcut] : [];

const govde = $('Not Webhook (POST)').first().json.body || {};
const islem = String(govde.islem || 'ekle').toLowerCase();

// "2026-08-25T18:30:00" · "18:30" · "yarın 09:00" · "30dk" · "2saat" · "25.08 14:00"
const zamanCoz = (ham) => {
  const s = String(ham || '').trim();
  if (!s) return null;
  const k = s.toLowerCase();
  let m;
  if ((m = k.match(/^(\d+)\s*(dk|dakika)\b/))) return new Date(Date.now() + Number(m[1]) * 60000);
  if ((m = k.match(/^(\d+)\s*(sa|saat)\b/))) return new Date(Date.now() + Number(m[1]) * 3600000);
  if ((m = k.match(/^(\d{1,2})[.\/](\d{1,2})(?:[.\/](\d{2,4}))?\s+(\d{1,2})[:.](\d{2})$/))) {
    const yil = m[3] ? (m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3])) : new Date().getFullYear();
    return new Date(yil, Number(m[2]) - 1, Number(m[1]), Number(m[4]), Number(m[5]), 0, 0);
  }
  if ((m = k.match(/^(yarın|yarin)(?:\s+(\d{1,2})[:.](\d{2}))?$/))) {
    const d = new Date();
    d.setDate(d.getDate() + 1);
    d.setHours(m[2] ? Number(m[2]) : 9, m[3] ? Number(m[3]) : 0, 0, 0);
    return d;
  }
  if ((m = k.match(/^(\d{1,2})[:.](\d{2})$/))) {
    const d = new Date();
    d.setHours(Number(m[1]), Number(m[2]), 0, 0);
    if (d.getTime() <= Date.now()) d.setDate(d.getDate() + 1);
    return d;
  }
  const d = new Date(s); // ISO biçimi
  return isNaN(d.getTime()) ? null : d;
};

let mesaj = '';
if (islem === 'ekle') {
  const metin = String(govde.metin || govde.not || '').trim();
  if (!metin) {
    mesaj = 'HATA: "metin" alanı zorunlu.';
  } else {
    const zaman = zamanCoz(govde.hatirlat);
    if (govde.hatirlat && !zaman) {
      mesaj = 'HATA: "hatirlat" alanı anlaşılamadı (örn. "18:30", "yarın 09:00", "30dk" veya ISO tarih).';
    } else {
      const yeniId = notlar.reduce((mx, n) => Math.max(mx, Number(n.id) || 0), 0) + 1;
      notlar.push({
        id: yeniId,
        metin,
        hatirlat: zaman ? zaman.toISOString() : null,
        durum: 'acik',
        olusturulma: new Date().toISOString(),
      });
      mesaj = zaman
        ? `Hatırlatma kuruldu (#${yeniId}): ${metin} — ${zaman.toLocaleString('tr-TR')}`
        : `Not eklendi (#${yeniId}): ${metin}`;
    }
  }
} else if (islem === 'sil') {
  const id = Number(govde.id);
  const not = notlar.find((n) => Number(n.id) === id);
  if (!not) {
    mesaj = `HATA: #${id} numaralı not bulunamadı.`;
  } else {
    notlar.splice(notlar.indexOf(not), 1);
    mesaj = `Not silindi (#${id}): ${not.metin}`;
  }
} else {
  mesaj = `HATA: bilinmeyen işlem "${islem}". Geçerli işlemler: ekle, sil.`;
}

const bekleyen = notlar.filter((n) => n.hatirlat && n.durum !== 'gonderildi').length;
return [{ json: { notlar, mesaj, hata: mesaj.startsWith('HATA'), bekleyenHatirlatma: bekleyen } }];

// Zamanı gelmiş hatırlatmaları bulur, 'gonderildi' işaretler ve mesaj metnini kurar.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const okunan = $input.first().json;
const ham = (okunan.data && okunan.data.notlar) || okunan.notlar || [];
const notlar = (Array.isArray(ham) ? ham : []).map((n) => ({ ...n }));

const simdi = Date.now();
const zamani = notlar.filter((n) => {
  if (!n || !n.hatirlat || n.durum === 'gonderildi') return false;
  const t = new Date(n.hatirlat).getTime();
  return Number.isFinite(t) && t <= simdi;
});

for (const n of zamani) {
  n.durum = 'gonderildi';
  n.gonderilme = new Date().toISOString();
}

const saat = (n) => new Date(n.hatirlat).toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' });
const text = zamani.length
  ? '⏰ Hatırlatma:\n' + zamani.map((n) => '• ' + n.metin + ' (' + saat(n) + ')').join('\n')
  : '';
const html = zamani.length
  ? '<div style="font-family:sans-serif;max-width:640px"><h2>⏰ Hatırlatma</h2><ul>' +
    zamani.map((n) => '<li style="margin:4px 0">' + esc(n.metin) + ' <span style="color:#999">(' + saat(n) + ')</span></li>').join('') +
    '</ul></div>'
  : '';
const konu = zamani.length
  ? '[n8n] ⏰ ' + (zamani.length === 1 ? zamani[0].metin.slice(0, 60) : zamani.length + ' hatırlatma')
  : '';

return [{ json: { notlar, adet: zamani.length, gonderilecek: zamani.length > 0, text, html, konu } }];

// Telegram kuruluysa hatırlatma oraya gider; değilse bu dal boş döner.
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: $input.first().json.text.slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE hatırlatma mail olarak gider (çift bildirim olmasın).
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
const j = $input.first().json;
return [{ json: { konu: j.konu, html: j.html } }];
